    rows = (
        delivery.objects.using(alias)
        .filter(channel="LEGACY", status="PENDING")
        .select_related("event")
    )
    for row in rows.iterator(chunk_size=100):
        event.objects.using(alias).create(
            alert_id=row.event.alert_id,
            outcome="CHANNEL_RETIRED",
            severity=row.event.severity,
            evidence={
                "delivery_id": row.pk,
                "previous_status": row.status,
                "reason": "LEGACY_TRANSPORT_DISABLED",
            },
        )
        delivery.objects.using(alias).filter(pk=row.pk).update(
            status="DEAD", last_error_code="LEGACY_TRANSPORT_DISABLED"
        )


